// Package fixture generates instance-based fixture factories for types annotated with //datlas:fixture.
package fixture

import (
	"bufio"
	"errors"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"golang.org/x/tools/go/packages"

	"github.com/moznion/go-datlas/internal/generator/loader"
	"github.com/moznion/go-datlas/internal/generator/naming"
	"github.com/moznion/go-datlas/internal/generator/output"
)

// FileName is the name of the generated file.
const FileName = "zz_fixture_gen.go"

// Config configures fixture generation.
type Config struct {
	// Dir is the directory patterns, OutDir and PolicyFile are resolved against.
	Dir string
	// Patterns select the packages to scan for //datlas:fixture types.
	Patterns []string
	// PolicyFile is a YAML file giving the fixture policy of types that cannot be annotated,
	// such as types generated by other tools. Optional.
	PolicyFile string
	// OutDir is the directory of the package the factory is generated into.
	OutDir string
	// PackageName overrides the name of the generated package.
	PackageName string
}

// Generate builds the fixture factory for every //datlas:fixture type found in cfg.Patterns
// and every type of cfg.PolicyFile.
//
// Without patterns and policy file, it builds the factory without any factory method,
// to which methods can be added by hand. When patterns are given but no fixture type remains,
// the result asks to remove a previously generated file; it is an error if there is none.
func Generate(cfg Config) (output.Result, error) {
	fail := func(err error) (output.Result, error) { return output.Result{}, err }
	outDir := cfg.OutDir
	if !filepath.IsAbs(outDir) {
		outDir = filepath.Join(cfg.Dir, outDir)
	}
	outDir, err := filepath.Abs(outDir)
	if err != nil {
		return fail(err)
	}
	outPkgPath, err := importPath(outDir)
	if err != nil {
		return fail(err)
	}
	pkgName := cfg.PackageName
	if pkgName == "" {
		if pkgName, err = packageName(outDir); err != nil {
			return fail(err)
		}
	}
	path := filepath.Join(outDir, FileName)

	var policy *policyFile
	if cfg.PolicyFile != "" {
		p := cfg.PolicyFile
		if !filepath.IsAbs(p) {
			p = filepath.Join(cfg.Dir, p)
		}
		if policy, err = parsePolicyFile(p); err != nil {
			return fail(err)
		}
	}
	handWritten, err := handWrittenMethods(outDir, pkgName)
	if err != nil {
		return fail(err)
	}
	for _, name := range []string{"Seed", "Faker"} {
		if pos, ok := handWritten[name]; ok {
			return fail(fmt.Errorf("%s: Factory.%s is declared by hand, but the generated factory declares it too", pos, name))
		}
	}
	hasGo, err := hasGoFiles(outDir)
	if err != nil {
		return fail(err)
	}

	var (
		fts      []FixtureType
		declared map[string]string
	)
	if len(cfg.Patterns) == 0 && policy == nil {
		// Only the factory itself, for hand-written methods.
		if hasGo {
			pkgs, err := loader.Load(outDir, ".")
			if err != nil {
				return fail(err)
			}
			declared = scopeOf(pkgs, outPkgPath)
		}
	} else {
		patterns := slices.Clone(cfg.Patterns)
		var extra []string
		if policy != nil {
			extra = append(extra, policy.packages()...)
		}
		if hasGo {
			// Loaded together with the rest, so that its wrap functions share their types.
			extra = append(extra, outPkgPath)
		}
		for _, p := range extra {
			if !slices.Contains(patterns, p) {
				patterns = append(patterns, p)
			}
		}
		pkgs, err := loader.Load(cfg.Dir, patterns...)
		if err != nil {
			return fail(err)
		}
		all, err := loader.Directives(pkgs)
		if err != nil {
			return fail(err)
		}
		// Only the packages matched by cfg.Patterns are scanned for //datlas:fixture types.
		scanned := map[string]bool{}
		if len(patterns) > len(cfg.Patterns) && len(cfg.Patterns) > 0 {
			if scanned, err = loader.PackagePaths(cfg.Dir, cfg.Patterns...); err != nil {
				return fail(err)
			}
		} else if len(cfg.Patterns) > 0 {
			for _, p := range pkgs {
				scanned[p.PkgPath] = true
			}
		}

		var (
			targets []target
			errs    []error
		)
		for _, d := range all {
			if d.Kind != loader.KindFixture || !scanned[d.Package.PkgPath] {
				continue
			}
			t, err := directiveTarget(d)
			if err != nil {
				errs = append(errs, err)
				continue
			}
			targets = append(targets, t)
		}
		if policy != nil {
			for _, pt := range policy.Types {
				t, err := policyTarget(pt, policy.Path, pkgs)
				if err != nil {
					errs = append(errs, err)
					continue
				}
				targets = append(targets, t)
			}
		}
		if err := errors.Join(errs...); err != nil {
			return fail(err)
		}
		if len(targets) == 0 {
			if _, err := os.Stat(path); err == nil {
				return output.Result{Path: path}, nil
			}
			where := strings.Join(cfg.Patterns, " ")
			if policy != nil {
				where = strings.TrimSpace(where + " " + policy.Path)
			}
			return fail(fmt.Errorf("no //datlas:fixture types found in %s", where))
		}

		reserved := map[string]string{}
		for name, pos := range handWritten {
			reserved[name] = "the hand-written method Factory." + name + " at " + pos
		}
		if fts, err = analyze(targets, outPkgPath, loader.NewEnums(cfg.Dir, pkgs, all), reserved, pkgs); err != nil {
			return fail(err)
		}
		if hasGo {
			declared = scopeOf(pkgs, outPkgPath)
		}
	}

	for _, name := range generatedIdents {
		if pos, ok := declared[name]; ok {
			return fail(fmt.Errorf("%s: %s is already declared in the output package, where the factory declares it too; generate the factory into another package with -out", pos, name))
		}
	}
	reserved := make([]string, 0, len(declared))
	for name := range declared {
		reserved = append(reserved, name)
	}
	src, err := render(pkgName, outPkgPath, fts, reserved)
	if err != nil {
		return fail(err)
	}
	return output.Result{Path: path, Src: src}, nil
}

// policyTarget resolves the type of a policy file entry among the loaded packages.
func policyTarget(pt policyType, file string, pkgs []*packages.Package) (target, error) {
	ref := pt.PkgPath + "." + pt.TypeName
	var pkg *packages.Package
	for _, p := range pkgs {
		if p.PkgPath == pt.PkgPath {
			pkg = p
		}
	}
	if pkg == nil || pkg.Types == nil {
		return target{}, fmt.Errorf("%s: package %s is not found", pt.Pos, pt.PkgPath)
	}
	obj, ok := pkg.Types.Scope().Lookup(pt.TypeName).(*types.TypeName)
	if !ok {
		return target{}, fmt.Errorf("%s: type %s is not declared in package %s", pt.Pos, pt.TypeName, pt.PkgPath)
	}
	if named, ok := obj.Type().(*types.Named); ok && named.TypeParams().Len() > 0 {
		return target{}, fmt.Errorf("%s: %s is generic, which is not supported", pt.Pos, ref)
	}
	st, ok := obj.Type().Underlying().(*types.Struct)
	if !ok {
		return target{}, fmt.Errorf("%s: %s is not a struct type", pt.Pos, ref)
	}
	return target{
		Pos:      pt.Pos,
		Package:  pkg,
		Type:     obj,
		Struct:   st,
		Name:     pt.Name,
		Plural:   pt.Plural,
		Owner:    ref + " of " + file,
		Rename:   "rename it with name: in " + file,
		Policies: pt.Fields,
		FieldPos: pt.FieldPos,
	}, nil
}

// generatedIdents are the package-level identifiers declared by the generated factory.
var generatedIdents = []string{"Option", "WithSeed", "WithClock", "WithNow", "WithTimePrecision", "WithT", "Factory", "New"}

// hasGoFiles reports whether dir holds Go files of the package other than the generated factory.
func hasGoFiles(dir string) (bool, error) {
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") && !strings.HasSuffix(e.Name(), "_test.go") && e.Name() != FileName {
			return true, nil
		}
	}
	return false, nil
}

// scopeOf returns the package-level identifiers of the package path among pkgs, with their positions.
func scopeOf(pkgs []*packages.Package, path string) map[string]string {
	declared := map[string]string{}
	for _, p := range pkgs {
		if p.PkgPath != path || p.Types == nil {
			continue
		}
		scope := p.Types.Scope()
		for _, name := range scope.Names() {
			declared[name] = p.Fset.Position(scope.Lookup(name).Pos()).String()
		}
	}
	return declared
}

// handWrittenMethods returns the methods of Factory declared by hand in the package pkgName in dir,
// with their positions. They are found syntactically: the loader hides the generated file,
// so Factory is undefined while loading and its methods cannot be resolved as types.
func handWrittenMethods(dir, pkgName string) (map[string]string, error) {
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	methods := map[string]string{}
	fset := token.NewFileSet()
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || name == FileName {
			continue
		}
		f, err := parser.ParseFile(fset, filepath.Join(dir, name), nil, parser.SkipObjectResolution)
		if err != nil {
			return nil, err
		}
		if f.Name.Name != pkgName {
			continue // e.g. an external test package
		}
		for _, decl := range f.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok || fd.Recv == nil || len(fd.Recv.List) != 1 {
				continue
			}
			recv := fd.Recv.List[0].Type
			if star, ok := recv.(*ast.StarExpr); ok {
				recv = star.X
			}
			if id, ok := recv.(*ast.Ident); ok && id.Name == "Factory" {
				methods[fd.Name.Name] = fset.Position(fd.Pos()).String()
			}
		}
	}
	return methods, nil
}

// importPath computes the import path of the package in dir from the enclosing go.mod.
// dir does not need to exist yet.
func importPath(dir string) (string, error) {
	for d := dir; ; d = filepath.Dir(d) {
		mod := filepath.Join(d, "go.mod")
		if _, err := os.Stat(mod); err == nil {
			modPath, err := modulePath(mod)
			if err != nil {
				return "", err
			}
			rel, err := filepath.Rel(d, dir)
			if err != nil {
				return "", err
			}
			if rel == "." {
				return modPath, nil
			}
			return modPath + "/" + filepath.ToSlash(rel), nil
		}
		if filepath.Dir(d) == d {
			return "", fmt.Errorf("%s is not inside a Go module", dir)
		}
	}
}

func modulePath(goMod string) (string, error) {
	f, err := os.Open(goMod)
	if err != nil {
		return "", err
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := strings.TrimSpace(s.Text())
		if rest, ok := strings.CutPrefix(line, "module"); ok && rest != "" && (rest[0] == ' ' || rest[0] == '\t') {
			return strings.Trim(strings.TrimSpace(rest), `"`), nil
		}
	}
	if err := s.Err(); err != nil {
		return "", err
	}
	return "", fmt.Errorf("%s: module directive not found", goMod)
}

// packageName returns the name of the package in dir: the name used by its existing
// non-generated files, or else the directory name.
func packageName(dir string) (string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return "", err
	}
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || name == FileName {
			continue
		}
		f, err := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, name), nil, parser.PackageClauseOnly)
		if err != nil {
			return "", err
		}
		return f.Name.Name, nil
	}
	name := strings.ReplaceAll(filepath.Base(dir), "-", "_")
	if !naming.IsIdentifier(name) {
		return "", fmt.Errorf("cannot derive a package name from %s; specify one explicitly", dir)
	}
	return name, nil
}
